style.css:
/* Full blackout mode */
* {
  background: #000 !important;
  color: #000 !important; /* hides text too */
  border-color: #000 !important;
}

/* Kill images, videos, everything */
img, video, iframe {
  display: none !important;
}

/* Force page to stay black */
html, body {
  background: #000 !important;
}
*
{
  color:#000000 !important;
}
